export const HARD_3 = [
  { words: ['Shrimp', 'Mantis Shrimp', 'Lobster', 'Crab'], oddOne: 1, category: 'True Crustaceans in the Same Broad Group as Lobsters and Crabs, Except One That\'s a Completely Different Kind of Animal Despite the Name', explanation: 'Shrimp, lobster, and crab are all decapod crustaceans, a specific group with ten legs. A mantis shrimp isn\'t closely related to true shrimp at all; it belongs to its own separate order entirely, famous for its powerful, punching claws.' },
  { words: ['Bullfrog', 'Toad', 'Tree Frog', 'Horned Toad'], oddOne: 3, category: 'True Amphibians, Except a Reptile Wearing a Toad\'s Name', explanation: 'Bullfrog, toad, and tree frog are all genuine amphibians. A "horned toad" (also called a horny toad) is actually a species of lizard, a true reptile, despite having "toad" right there in its name.' },
  { words: ['Flying Squirrel', 'Flying Fish', 'Flying Lemur', 'Housefly'], oddOne: 3, category: 'Animals Named "Flying" That Actually Just Glide, Except an Insect That Genuinely Flies Under Its Own Power', explanation: 'Flying squirrel, flying fish, and flying lemur (also called a colugo) can\'t actually flap and fly; they glide through the air using skin flaps or fins. A housefly is a true, powered flier, flapping real wings the entire time.' },
  { words: ['Silverfish', 'Firefly', 'Butterfly', 'Ladybird'], oddOne: 0, category: 'Insects With a Misleading Animal Name Tucked Inside, Except the One That Can\'t Even Fly', explanation: 'Firefly, butterfly, and ladybird all have wings and can fly, despite the misleading names tucked inside them. A silverfish has no wings at all and can\'t fly one bit, on top of not being a fish either.' },
  { words: ['Woodpecker', 'Kingfisher', 'Hummingbird', 'Penguin'], oddOne: 3, category: 'Birds Named for What They Actually Do, Except a Bird That Can\'t Do the One Thing Birds Are Known For', explanation: 'Woodpecker (pecks wood), kingfisher (catches fish), and hummingbird (hums while it flies) are all named for a real, distinctive behavior. A penguin is famously the one major bird group that cannot fly at all.' },
  { words: ['Roadrunner', 'Ostrich', 'Emu', 'Hummingbird'], oddOne: 3, category: 'Flightless or Ground-Loving Birds Built for Speed on Foot, Except a Bird Built for Hovering in Place', explanation: 'Roadrunner, ostrich, and emu are all birds famous for outrunning danger on foot rather than flying away. A hummingbird is the opposite specialist: built to hover perfectly still in midair, not to sprint.' },
  { words: ['New Zealand', 'Kiwi', 'All Blacks', 'Fig'], oddOne: 3, category: 'Things Strongly Associated With New Zealand, Except a Completely Unrelated Fruit', explanation: 'New Zealand, the kiwi bird (the country\'s national symbol), and the All Blacks rugby team are all closely tied to New Zealand\'s identity. A fig is just a fruit with no particular connection to the country at all.' },
  { words: ['Kiwifruit', 'Kiwi Bird', 'New Zealander', 'Pineapple'], oddOne: 3, category: 'Things All Commonly Called "Kiwi," Except a Completely Different Tropical Fruit', explanation: 'Kiwifruit, the kiwi bird, and a New Zealander (nicknamed "a Kiwi") are all genuinely, commonly called "kiwi." A pineapple has never once been nicknamed that, no matter how tropical it looks.' },
  { words: ['Panama Canal', 'Suez Canal', 'English Channel', 'Erie Canal'], oddOne: 2, category: 'Man-Made Canals Built to Shorten Sea Voyages, Except a Natural Body of Water', explanation: 'Panama Canal, Suez Canal, and Erie Canal were all deliberately dug by people to connect two bodies of water. The English Channel is a completely natural strait that\'s just always been there, no digging required.' },
  { words: ['Hoover Dam', 'Three Gorges Dam', 'Beaver Dam', 'Grand Coulee Dam'], oddOne: 2, category: 'Massive Human-Engineered Dams, Except One Built Entirely by an Animal', explanation: 'Hoover Dam, Three Gorges Dam, and Grand Coulee Dam are all enormous feats of human engineering. A beaver dam is built by, well, beavers, using sticks and mud, no blueprints or bulldozers required.' },
  { words: ['Beehive', 'Anthill', 'Beaver Dam', 'Skyscraper'], oddOne: 3, category: 'Impressive Structures Built by Animals, Except One Built Entirely by People', explanation: 'Beehive, anthill, and beaver dam are all remarkable structures built by animals working together instinctively. A skyscraper is a purely human invention, requiring blueprints, steel, and a whole construction crew.' },
  { words: ['Termite Mound', 'Beehive', 'Spider Web', 'Bird Nest'], oddOne: 2, category: 'Structures Built by an Animal That Lives There in a Group, Except a Structure Built by a Loner', explanation: 'Termite mound, beehive, and bird nest are typically built and shared by a colony or family group working together. A spider web is spun by a single spider, working entirely alone.' },
  { words: ['Honeybee', 'Ant', 'Termite', 'Praying Mantis'], oddOne: 3, category: 'Social Insects That Live in Highly Organized Colonies, Except a Famously Solitary Hunter', explanation: 'Honeybee, ant, and termite all live in large, cooperative colonies with a queen and specific worker roles. A praying mantis lives and hunts entirely alone, with no colony or queen at all.' },
  { words: ['Queen Bee', 'Queen Ant', 'Queen Termite', 'Queen Elizabeth II'], oddOne: 3, category: 'Insect Royalty Whose "Queen" Title Is Purely a Biological Role, Except an Actual Human Monarch', explanation: 'Queen bee, queen ant, and queen termite all earn the title purely by being the one reproductive female of the colony, not through any royal ceremony. Queen Elizabeth II was an actual, real human monarch, crowned in a real coronation.' },
  { words: ['Worker Bee', 'Worker Ant', 'Soldier Termite', 'CEO'], oddOne: 3, category: 'Roles Within an Insect Colony, Except a Job Title From a Human Office', explanation: 'Worker bee, worker ant, and soldier termite are all specific roles insects are born into within their colony. A CEO is a human job title, earned through a career, not built into your biology from birth.' },
  { words: ['Honey', 'Beeswax', 'Royal Jelly', 'Maple Syrup'], oddOne: 3, category: 'Things Produced Directly by Honeybees, Except a Sweet Syrup That Comes From a Tree Instead', explanation: 'Honey, beeswax, and royal jelly are all substances honeybees themselves produce inside the hive. Maple syrup comes from boiling down the sap of a maple tree, no bees involved in making it at all.' },
  { words: ['Silk', 'Honey', 'Wool', 'Cotton'], oddOne: 3, category: 'Materials That Come From an Animal, Except a Fiber That Grows on a Plant', explanation: 'Silk (from silkworms), honey (from bees), and wool (from sheep) all come directly from an animal. Cotton grows as a soft fiber around the seeds of the cotton plant, no animal involved.' },
  { words: ['Wool', 'Cashmere', 'Mohair', 'Linen'], oddOne: 3, category: 'Fabrics Made From Animal Hair, Except a Fabric Made From a Plant Stem', explanation: 'Wool (sheep), cashmere (goats), and mohair (Angora goats) are all fabrics spun from animal hair or fur. Linen is made from the fibers of the flax plant\'s stem, no animal involved whatsoever.' },
  { words: ['Cotton', 'Linen', 'Hemp', 'Silk'], oddOne: 3, category: 'Natural Fabrics That Come From a Plant, Except a Fiber Spun by an Insect', explanation: 'Cotton, linen, and hemp are all plant-based fibers, grown in a field and harvested. Silk comes from the cocoon spun by a silkworm, an animal fiber, not a plant one.' },
  { words: ['Leather', 'Suede', 'Wool', 'Denim'], oddOne: 3, category: 'Materials That Come From an Animal, Except a Fabric Woven From Cotton', explanation: 'Leather and suede both come from animal hide, and wool comes from a sheep\'s fleece. Denim is a sturdy cotton fabric, woven from plant fiber, no animal involved.' },
  { words: ['Pearl', 'Ivory', 'Leather', 'Plastic'], oddOne: 3, category: 'Materials That Originally Come From a Living Thing, Except a Material Made Entirely in a Factory', explanation: 'Pearl (from an oyster), ivory (from a tusk), and leather (from hide) all originally come from a living creature. Plastic is synthetic, manufactured from chemicals and petroleum, no living source at all.' },
  { words: ['Coral', 'Amber', 'Pearl', 'Glass'], oddOne: 3, category: 'Materials Used in Jewelry That Originally Came From a Living Organism, Except a Material Made From Melted Sand', explanation: 'Coral, amber (fossilized tree resin), and pearl all trace back to a living organism at some point. Glass is made by melting sand at extremely high temperatures, no living source involved.' },
  { words: ['Glass', 'Sand', 'Ceramic', 'Wood'], oddOne: 3, category: 'Materials Made by Heating Something to an Extreme Temperature, Except a Material You\'d Just Cut Down', explanation: 'Glass and ceramic are both made by heating raw material (like sand or clay) to a very high temperature until it transforms. Wood is simply cut from a living tree, no furnace involved at all.' },
  { words: ['Charcoal', 'Diamond', 'Coal', 'Oxygen'], oddOne: 3, category: 'Substances Made Mostly or Entirely of Carbon, Except an Element With No Carbon in It Whatsoever', explanation: 'Charcoal, diamond, and coal are all, remarkably, forms or sources of pure or near-pure carbon. Oxygen is a completely different element, the very thing carbon needs in order to burn.' },
  { words: ['Rust', 'Fire', 'Fireworks', 'Ice Melting'], oddOne: 3, category: 'Chemical Reactions Involving Oxygen, Except a Purely Physical Change With No New Substance Formed', explanation: 'Rust, fire, and fireworks are all genuine chemical reactions, creating brand-new substances through oxidation or combustion. Ice melting is just a physical change of state, water is still water, no new substance involved.' },
  { words: ['Water Boiling', 'Ice Melting', 'Butter Melting', 'Wood Burning'], oddOne: 3, category: 'Physical Changes You Can Easily Reverse, Except a Chemical Change You Can\'t Undo', explanation: 'Water boiling, ice melting, and butter melting are all physical changes: cool them back down and you get the exact same substance you started with. Wood burning is a chemical change, turning wood into ash and smoke that can never turn back into wood.' },
];

export const HARD_4 = [
  { words: ['Sugar Dissolving', 'Salt Dissolving', 'Milk Souring', 'Ice Cube Melting'], oddOne: 2, category: 'Physical Changes You Can Reverse by Evaporating or Freezing, Except a Chemical Change You Can\'t Undo', explanation: 'Sugar dissolving, salt dissolving, and ice melting are all physical changes; dry out the water or freeze it back and you get the original substance again. Milk souring is a genuine chemical change caused by bacteria, and there\'s no reversing spoiled milk back to fresh.' },
  { words: ['Baking a Cake', 'Toasting Bread', 'Frying an Egg', 'Melting Chocolate'], oddOne: 3, category: 'Cooking Processes That Chemically Change the Food Forever, Except One That\'s Just a Physical Change You Can Undo', explanation: 'Baking a cake, toasting bread, and frying an egg all trigger chemical reactions that permanently transform the ingredients; you can never turn a cake back into raw batter. Melting chocolate is just a physical change: let it cool back down, and it solidifies right back into chocolate.' },
  { words: ['Popcorn Popping', 'Rusting Metal', 'Digesting Food', 'Freezing Water'], oddOne: 3, category: 'Irreversible Chemical Changes, Except a Reversible Physical One', explanation: 'Popcorn popping, rusting metal, and digesting food are all one-way chemical transformations you can\'t undo. Freezing water is purely physical: melt it, and it\'s just water again, no different from before.' },
  { words: ['Photosynthesis', 'Respiration', 'Digestion', 'Evaporation'], oddOne: 3, category: 'Biological Chemical Processes Inside Living Things, Except a Physical Process That Happens to Water Anywhere', explanation: 'Photosynthesis, respiration, and digestion are all chemical processes that happen specifically inside living organisms. Evaporation is a purely physical process, and it happens to any puddle or ocean, alive or not.' },
  { words: ['Lungs', 'Gills', 'Tracheae', 'Stomach'], oddOne: 3, category: 'Ways Different Animals Actually Breathe, Except an Organ Built for Digesting Food', explanation: 'Lungs (mammals), gills (fish), and tracheae (a network of tiny tubes insects use) are all real breathing systems evolved by different animals. A stomach\'s job is breaking down food, nothing to do with breathing at all.' },
  { words: ['Heart', 'Brain', 'Kidney', 'Fingernail'], oddOne: 3, category: 'Vital Organs You Cannot Survive Without, Except Something You Can Trim Off With No Harm at All', explanation: 'Heart, brain, and kidney are all essential organs; losing any of them (without a transplant or dialysis) is fatal. A fingernail can be clipped again and again with zero consequence to your health.' },
  { words: ['Hair', 'Fingernails', 'Skin Cells', 'Heart'], oddOne: 3, category: 'Parts of You That Constantly Regenerate Throughout Your Life, Except an Organ That Barely Regenerates at All', explanation: 'Hair, fingernails, and skin cells are all constantly shedding and regrowing your entire life. Heart muscle cells barely regenerate once you\'re an adult, which is exactly why heart damage is so serious.' },
  { words: ['Liver', 'Skin', 'Blood', 'Tooth Enamel'], oddOne: 3, category: 'Parts of Your Body That Can Regenerate or Heal Themselves, Except the One Part That Never Can', explanation: 'Liver, skin, and blood can all regenerate or heal after damage, the liver famously so. Tooth enamel has no living cells in it at all once it forms, so it can never repair or regrow once it\'s damaged.' },
  { words: ['Broken Bone', 'Cut Skin', 'Sprained Ankle', 'Cavity'], oddOne: 3, category: 'Injuries Your Body Can Heal on Its Own Given Time, Except Damage That Only a Dentist Can Fix', explanation: 'A broken bone, cut skin, and sprained ankle can all heal naturally over time, given rest and care. A cavity in a tooth never heals itself; the enamel is gone for good, and only a dentist\'s filling can fix it.' },
  { words: ['Adult Tooth', 'Baby Tooth', 'Wisdom Tooth', 'Shark Tooth'], oddOne: 3, category: 'Teeth Humans Only Ever Get One Set Of, Except an Animal That Regrows Its Teeth Constantly', explanation: 'Adult teeth, baby teeth, and wisdom teeth are all part of the two total sets of teeth a human ever gets in a lifetime. A shark regrows and replaces its teeth constantly, sometimes producing thousands over its lifetime.' },
  { words: ['Shark', 'Crocodile', 'Elephant', 'Human'], oddOne: 3, category: 'Animals That Can Regrow Their Teeth Throughout Their Whole Life, Except the One Stuck With Just Two Sets', explanation: 'Shark, crocodile, and elephant can all regrow teeth repeatedly across their lifetime (an elephant even grows new molars as old ones wear down). Humans only ever get two sets total: baby teeth, then one single set of adult teeth for the rest of their life.' },
  { words: ['Elephant Tusk', 'Rhino Horn', 'Beaver Tooth', 'Antler'], oddOne: 3, category: 'Things Made of Material That Keeps Growing Throughout an Animal\'s Whole Life, Except Something That\'s Shed and Regrown Fresh Every Year', explanation: 'Elephant tusk, rhino horn, and beaver tooth all keep continuously growing for the animal\'s entire life, which is why beavers must constantly gnaw wood to wear theirs down. An antler is completely shed and regrown from scratch every single year, not a continuously growing structure at all.' },
  { words: ['Antler', 'Horn', 'Tusk', 'Claw'], oddOne: 0, category: 'Hard Structures an Animal Keeps for Life, Except the One Structure That\'s Regrown Fresh Every Year', explanation: 'Horn, tusk, and claw are all permanent structures the animal keeps and simply maintains for its whole life. An antler is the one exception: it\'s shed entirely and regrown from scratch every single year.' },
  { words: ['Bird Feather', 'Snake Skin', 'Deer Antler', 'Turtle Shell'], oddOne: 3, category: 'Body Coverings That Get Shed or Replaced Periodically, Except a Shell an Animal Can Never Leave Behind', explanation: 'Bird feathers molt, snake skin sheds, and deer antlers drop off and regrow every year. A turtle\'s shell is fused to its actual skeleton; it can never shed or crawl out of it, unlike the classic cartoon idea of turtles switching shells.' },
  { words: ['Hermit Crab', 'Snail', 'Turtle', 'Nautilus'], oddOne: 2, category: 'Animals That Actually Live Inside a Shell That Isn\'t Fused to Their Body, Except an Animal Whose Shell Is Literally Part of Its Skeleton', explanation: 'Hermit crab (which borrows and swaps shells its whole life), snail, and nautilus all carry a shell that\'s a separate structure they can, in some cases, leave or trade. A turtle\'s shell is fused directly to its spine and ribs; it is its skeleton, not a separate house.' },
  { words: ['Hermit Crab', 'Snail', 'Clam', 'Octopus'], oddOne: 3, category: 'Mollusks or Shell-Dwellers, Except an Animal With No Shell At All', explanation: 'Hermit crab (which borrows an empty mollusk shell), snail, and clam are all associated with a hard protective shell. An octopus is a soft-bodied cephalopod with no shell whatsoever, relying on speed and camouflage instead.' },
  { words: ['Snail', 'Slug', 'Octopus', 'Squid'], oddOne: 0, category: 'Soft-Bodied Mollusks With No Shell of Their Own, Except the One That Still Carries a Hard Shell on Its Back', explanation: 'Slug, octopus, and squid are all mollusks that ditched a hard external shell over the course of evolution. A snail still carries its coiled shell everywhere it goes.' },
  { words: ['Cheetah', 'Greyhound', 'Sailfish', 'Snail'], oddOne: 3, category: 'Some of the Fastest Animals in Their Environment, Except One of the Slowest Animals Alive', explanation: 'Cheetah, greyhound, and sailfish are all celebrated for blazing speed on land, on foot, or in the water. A snail is famous for the exact opposite: one of the slowest-moving creatures on Earth.' },
  { words: ['Snail', 'Sloth', 'Tortoise', 'Hare'], oddOne: 3, category: 'Animals Famous for Being Extremely Slow, Except the Animal That Lost a Very Famous Race Because It Got Overconfident', explanation: 'Snail, sloth, and tortoise are all genuinely, biologically slow-moving animals. A hare is actually one of the fastest animals around; it only lost its famous fable race to the tortoise because it took a very ill-advised nap.' },
];

export const HARD_5 = [
  { words: ['Venus', 'Mercury', 'Mars', 'Ceres'], oddOne: 3, category: 'The Four Planets Closest to the Sun, Except a Dwarf Planet in the Asteroid Belt', explanation: 'Venus, Mercury, and Mars are three of the four rocky, inner planets closest to the sun. Ceres is a dwarf planet, and it actually sits out in the asteroid belt, well past Mars.' },
  { words: ['Mercury', 'Venus', 'Earth', 'Titan'], oddOne: 3, category: 'Planets of Our Solar System, Except a Moon of Saturn', explanation: 'Mercury, Venus, and Earth are all genuine planets orbiting the sun directly. Titan is Saturn\'s largest moon, orbiting Saturn, not the sun.' },
  { words: ['Io', 'Europa', 'Ganymede', 'Luna'], oddOne: 3, category: 'Moons of Jupiter, Except Earth\'s Own Moon', explanation: 'Io, Europa, and Ganymede are all moons orbiting Jupiter. Luna, the formal name for Earth\'s moon, orbits Earth instead, no relation to Jupiter at all.' },
  { words: ['Deimos', 'Phobos', 'Luna', 'Charon'], oddOne: 2, category: 'Moons of Planets or Dwarf Planets Other Than Earth, Except Earth\'s Very Own Moon', explanation: 'Deimos and Phobos orbit Mars, and Charon orbits the dwarf planet Pluto. Luna is Earth\'s own moon, the only one on this list actually orbiting our planet.' },
  { words: ['Sun', 'Sirius', 'Betelgeuse', 'Europa'], oddOne: 3, category: 'Actual Stars, Except a Moon of Jupiter', explanation: 'The Sun, Sirius, and Betelgeuse are all genuine, self-igniting stars burning through nuclear fusion. Europa is a moon of Jupiter, an icy satellite with no light of its own.' },
  { words: ['Sirius', 'Canopus', 'Betelgeuse', 'Proxima Centauri'], oddOne: 3, category: 'Bright Stars You Can Actually See With the Naked Eye, Except the Closest Star to Us That You Can\'t', explanation: 'Sirius, Canopus, and Betelgeuse are all bright enough to easily spot in the night sky without any equipment. Proxima Centauri is the single closest star to our solar system, but it\'s such a faint red dwarf that you\'d need a telescope to see it at all.' },
  { words: ['The Big Dipper', 'Orion\'s Belt', 'The Little Dipper', 'Ursa Major'], oddOne: 1, category: 'Recognizable Star Patterns (Asterisms or Whole Constellations), Except a Pattern That\'s Only Part of a Bigger Official Constellation', explanation: 'The Big Dipper (part of Ursa Major), Little Dipper, and Ursa Major itself are all widely recognized star groupings, with the Big Dipper and Ursa Major even overlapping. Orion\'s Belt is just three stars that make up one small section of the much larger constellation Orion.' },
  { words: ['Orion', 'Ursa Major', 'Cassiopeia', 'The Big Dipper'], oddOne: 3, category: 'Officially Recognized Constellations, Except an Asterism That\'s Just Part of One', explanation: 'Orion, Ursa Major, and Cassiopeia are all among the 88 officially recognized constellations. The Big Dipper is a well-known asterism, a recognizable star pattern, but it\'s only a piece of the larger official constellation Ursa Major.' },
  { words: ['Comet', 'Asteroid', 'Meteoroid', 'Satellite'], oddOne: 3, category: 'Natural Objects Flying Through Space, Except Something Humans Actually Built', explanation: 'Comet, asteroid, and meteoroid are all natural space debris, leftover material from the early solar system. A satellite (unless it\'s a natural one like a moon) usually refers to a human-made object launched into orbit.' },
  { words: ['Meteor', 'Meteorite', 'Meteoroid', 'Meteorologist'], oddOne: 3, category: 'Words for Space Rock at Different Stages of Its Journey, Except a Job Title for Someone Who Studies the Weather', explanation: 'Meteoroid (rock in space), meteor (it burning up in the atmosphere), and meteorite (what\'s left once it lands) are all just one object at three different stages. A meteorologist studies weather, with a name that only sounds related by coincidence.' },
  { words: ['Solar Eclipse', 'Lunar Eclipse', 'Supermoon', 'Sunspot'], oddOne: 3, category: 'Events Caused by the Alignment or Position of the Sun and Moon, Except Something That Happens on the Sun\'s Own Surface', explanation: 'Solar eclipse, lunar eclipse, and supermoon are all about how the Sun, Moon, and Earth line up or how close the Moon happens to be. A sunspot is a cooler, darker patch on the Sun\'s own surface, caused by its magnetic activity, nothing to do with the Moon.' },
  { words: ['High Tide', 'Low Tide', 'Supermoon', 'Sunburn'], oddOne: 3, category: 'Things Influenced by the Moon\'s Gravity or Position, Except Something Caused by Ultraviolet Rays', explanation: 'High tide, low tide, and a supermoon are all directly tied to the Moon\'s position and gravitational pull on Earth\'s oceans. A sunburn comes from ultraviolet radiation from the Sun, nothing to do with the Moon at all.' },
  { words: ['Ocean Tides', 'Werewolf Legends', 'Supermoons', 'Photosynthesis'], oddOne: 3, category: 'Things Genuinely or Legendarily Linked to the Moon, Except a Process Powered Entirely by the Sun', explanation: 'Ocean tides are genuinely caused by the Moon\'s gravity, werewolf legends are traditionally tied to the full moon, and supermoons are literally a moon phenomenon. Photosynthesis is powered by sunlight, requiring the Sun, not the Moon, to work at all.' },
  { words: ['Chlorophyll', 'Sunlight', 'Carbon Dioxide', 'Glucose'], oddOne: 3, category: 'What a Plant Needs to Start Photosynthesis, Except the Sugary Result It Actually Produces', explanation: 'Chlorophyll, sunlight, and carbon dioxide are all necessary ingredients a plant needs to begin photosynthesis. Glucose is the sugary product that comes out the other end, the plant\'s own homemade food, not something it starts with.' },
  { words: ['Oxygen', 'Glucose', 'Water', 'Nitrogen'], oddOne: 3, category: 'Things Produced or Used Up During Photosynthesis, Except a Gas That Plants Don\'t Use for the Process at All', explanation: 'Oxygen and glucose are both produced by photosynthesis, and water is a key ingredient plants take in through their roots to make it happen. Nitrogen is important for plant growth in other ways, but it plays no role in the photosynthesis reaction itself.' },
  { words: ['Roots', 'Stem', 'Leaves', 'Petal'], oddOne: 3, category: 'Parts of a Plant Focused on Survival, Growth, and Food Production, Except a Part That\'s Mainly There to Attract a Pollinator', explanation: 'Roots, stem, and leaves are all working parts focused on absorbing water, standing tall, and making food through photosynthesis. A petal\'s main job is just being colorful and attractive to bees and other pollinators.' },
  { words: ['Pollen', 'Nectar', 'Petal', 'Thorn'], oddOne: 3, category: 'Parts of a Flower That Help Attract or Reward a Pollinator, Except a Part That\'s Purely There for Defense', explanation: 'Pollen, nectar, and petal all play some role in attracting a bee or butterfly and helping pollination happen. A thorn exists purely to defend the plant from being eaten, nothing to do with attracting pollinators at all.' },
  { words: ['Rose Thorn', 'Cactus Spine', 'Porcupine Quill', 'Bee Sting'], oddOne: 3, category: 'Sharp, Pointy Defenses That Stay Attached to the Owner, Except a Defense That Detaches and Costs Its Owner Its Life', explanation: 'A rose thorn, cactus spine, and porcupine quill can all poke an attacker without the plant or animal losing anything permanent. A honeybee\'s barbed stinger tears loose after stinging, which is fatal for the bee itself.' },
];

